            <style>
  .player-profile-card {
    background: #ffffff;
    border: 4px solid #000000;
    box-shadow: 8px 8px 0px #000000;
    padding: 25px;
    display: flex;
    gap: 20px;
    align-items: center;
    margin-bottom: 30px;
    transition: transform 0.2s steps(2);
  }

  .player-profile-card:hover {
    transform: translate(-4px, -4px);
    box-shadow: 12px 12px 0px var(--primary); /* Puxa a cor do XML */
  }

  .player-avatar-box {
    width: 120px; 
    height: 120px;
    border: 4px solid #000;
    background: #eeeeee;
    flex-shrink: 0;
  }

  .player-avatar-box img {
    width: 100%; 
    height: 100%; 
    object-fit: cover; 
    image-rendering: pixelated;
  }

  .player-stats-bar {
    height: 15px; 
    background: #dddddd; 
    border: 2px solid #000; 
    width: 100%; 
    margin-top: 5px;
  }

  .player-stats-fill {
    height: 100%; 
    background: var(--primary); 
    width: 0%; /* O JavaScript vai animar isso */
    transition: width 1.5s steps(10);
  }

  /* Responsividade: Empilha no celular */
  @media (max-width: 768px) {
    .player-profile-card { 
      flex-direction: column; 
      text-align: center; 
    }
  }
</style>

<div class="player-profile-card reveal" id="player-profile-card">

  <div class="player-avatar-box">
    <img src="https://placehold.co/120x120/000/0f0?text=P1" alt="Foto do Player 1" />
  </div>

  <div class="player-info-box w-100">
    <h3 class="retro-font h5 mb-2">@NOME_DO_ESPECIALISTA</h3>
    <p class="small text-muted mb-3">Mestre em conversão de vendas e otimização de sistemas 8-bits.</p>

    <div class="stats-container mt-3">

      <div class="small retro-font" style="font-size: 0.55rem;">ESTRATÉGIA</div>
      <div class="player-stats-bar">
        <div class="player-stats-fill bg-success" data-target="95%"></div>
      </div>

      <div class="small retro-font mt-2" style="font-size: 0.55rem;">TECNOLOGIA</div>
      <div class="player-stats-bar">
        <div class="player-stats-fill bg-info" data-target="85%"></div>
      </div>

    </div>
  </div>

</div>

<script>
  // Script isolado para não dar conflito com o tema principal
  (function() {
    const initProfileStats = () => {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if(entry.isIntersecting) {
            // Puxa as barras de status e aplica a largura definida pelo cliente
            const fills = entry.target.querySelectorAll('.player-stats-fill');
            fills.forEach(fill => {
              const targetWidth = fill.getAttribute('data-target');
              fill.style.width = targetWidth;
            });
            // Opcional: para de observar depois que animar a primeira vez
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.3 }); // Dispara quando 30% do card aparecer na tela

      const profileCard = document.getElementById('player-profile-card');
      if(profileCard) observer.observe(profileCard);
    };

    // Garante que roda independentemente da ordem de carregamento
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initProfileStats);
    } else {
      initProfileStats();
    }
  })();
</script>











