<style>
.main-post-pixel {
  background: #fff;
  border: 4px double #000;
  box-shadow: 10px 10px 0px #000;
  margin-bottom: 50px;
  position: relative;
  overflow: hidden;
}

/* Container da Imagem com Efeito CRT */
.pixel-img-container {
  position: relative;
  border-bottom: 4px solid #000;
  background: #000;
  overflow: hidden;
}

.post-main-img {
  width: 100%;
  height: auto;
  display: block;
  image-rendering: pixelated;
  transition: transform 0.5s steps(4);
}

.main-post-pixel:hover .post-main-img {
  transform: scale(1.05);
}

/* Efeito de Scanlines (Linhas de TV antiga) */
.scanlines {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.1) 50%), 
              linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03));
  background-size: 100% 4px, 3px 100%;
  z-index: 2;
  pointer-events: none;
}

/* Conteúdo */
.post-content-area { padding: 30px; }

.post-main-title {
  color: #000;
  font-size: 1.2rem;
  margin-bottom: 20px;
  line-height: 1.4;
}

.post-text-body {
  color: #444;
  font-size: 0.9rem;
  line-height: 1.8;
}

/* Lista estilo RPG */
.quest-requirements {
  list-style: none;
  padding: 0;
  margin-top: 20px;
}

.quest-requirements li::before {
  content: "> ";
  color: var(--primary);
  font-family: var(--font-pixel);
}

/* Footer do Post */
.post-footer-area {
  padding: 20px 30px;
  background: #f9f9f9;
  border-top: 2px dashed #000;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.date-stamp { font-size: 0.6rem; color: #888; }

.post-meta-tags {
  position: absolute;
  top: 15px; left: 15px;
  z-index: 3;
  display: flex;
  gap: 10px;
}

.tag-id, .tag-level {
  background: #000;
  color: #fff;
  padding: 5px 10px;
  font-size: 0.5rem;
}

.tag-level { background: var(--primary); }
</style>
<script>
//<![CDATA[
(function() {
  const titles = document.querySelectorAll('.post-main-title');

  titles.forEach(title => {
    title.addEventListener('mouseover', () => {
      if(!title.dataset.original) title.dataset.original = title.innerText;

      let iterations = 0;
      const interval = setInterval(() => {
        title.innerText = title.innerText.split("")
          .map((char, index) => {
            if(index < iterations) return title.dataset.original[index];
            return String.fromCharCode(65 + Math.floor(Math.random() * 26));
          })
          .join("");

        if(iterations >= title.dataset.original.length) clearInterval(interval);
        iterations += 1/3;
      }, 30);
    });
  });
})();
//]]>
</script>











