              <style>
  .quest-board-card {
    background-color: #ffffff;
    background-image: radial-gradient(#dddddd 2px, transparent 2px);
    background-size: 20px 20px;
    border: 4px dashed var(--primary);
    box-shadow: 8px 8px 0px #000000;
    padding: 40px 20px;
    transition: transform 0.2s steps(2);
  }
  .quest-board-card:hover { transform: translateY(-4px); box-shadow: 12px 12px 0px #000000; }

  .pixel-input {
    border: 4px solid #000000; padding: 12px 15px; font-family: var(--font-pixel);
    font-size: 0.6rem; outline: none; width: 100%; max-width: 350px;
    box-shadow: inset 4px 4px 0px rgba(0,0,0,0.05); transition: border-color 0.1s;
  }
  .pixel-input:focus { border-color: var(--primary); }

  .quest-icon { font-size: 3rem; animation: floatItem 2s steps(4) infinite; }
  @keyframes floatItem { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
</style>

<div class="col-md-10 mx-auto reveal">
  <div class="quest-board-card text-center">

    <div class="quest-icon mb-3">📜</div>

    <h3 class="retro-font h5 mb-3 text-uppercase" style="color: var(--primary);">[ NEW QUEST AVAILABLE ]</h3>
    <p class="small text-muted mb-4 mx-auto" style="max-width: 500px; font-weight: 500;">
      Junte-se à nossa Guilda! Insira o seu e-mail para receber atualizações do sistema e loot exclusivo direto na sua caixa de entrada.
    </p>

    <form id="guild-form" action="https://formsubmit.co/SEU_EMAIL_AQUI@GMAIL.COM" method="POST" class="d-flex justify-content-center gap-3 flex-wrap align-items-center">

      <input type="hidden" name="_captcha" value="false" />
      <input type="hidden" name="_subject" value="Novo Lead: Inscrição na Guilda!" />

      <input type="email" name="email" id="player-email" class="pixel-input" placeholder="PLAYER@EMAIL.COM" required />
      <button type="submit" class="btn-pixel" style="padding: 14px 25px; font-size: 0.7rem;">JOIN_GUILD</button>
    </form>

    <div id="quest-success" class="retro-font text-success mt-4" style="display: none; font-size: 0.6rem;">
      > XP GAINED! Bem-vindo à Guilda. Verifique seu inventário (e-mail).
    </div>

    <div id="quest-error" class="retro-font text-danger mt-4" style="display: none; font-size: 0.6rem;">
      > SYSTEM ERROR! Falha ao enviar dados. Tente novamente.
    </div>

  </div>
</div>

<script>
  (function() {
    const guildForm = document.getElementById('guild-form');
    const successMsg = document.getElementById('quest-success');
    const errorMsg = document.getElementById('quest-error');

    if(guildForm) {
      guildForm.addEventListener('submit', function(e) {
        e.preventDefault(); // Impede o redirecionamento padrão

        const btn = guildForm.querySelector('button');
        const formAction = guildForm.getAttribute('action');
        const formData = new FormData(guildForm);

        // Efeito Visual de Carregamento
        const originalText = btn.innerText;
        btn.innerText = "LOADING...";
        btn.style.opacity = "0.7";
        btn.disabled = true;

        // Envia os dados em segundo plano (AJAX/Fetch)
        fetch(formAction, {
          method: 'POST',
          body: formData,
          headers: { 'Accept': 'application/json' }
        })
        .then(response => {
          if (response.ok) {
            guildForm.style.display = 'none';
            successMsg.style.display = 'block';
            console.log('SFX: Level_Up.wav - Lead Capturado com Sucesso!');
          } else {
            throw new Error('Falha na requisição');
          }
        })
        .catch(error => {
          // Em caso de erro
          errorMsg.style.display = 'block';
          btn.innerText = "TRY_AGAIN";
          btn.style.opacity = "1";
          btn.disabled = false;
        });
      });
    }
  })();
</script>










