    //
    document.addEventListener('DOMContentLoaded', () => {

      // 2. TYPEWRITER EFFECT PARA NPCs
      const typeWriter = (el) => {
        const text = el.innerHTML; el.innerHTML = ''; let i = 0;
        const interval = setInterval(() => {
          if(i < text.length) { el.innerHTML += text.charAt(i); i++; }
          else clearInterval(interval);
        }, 30);
      };

      // 3. TITLE GLITCH EFFECT (MAIN POST)
      document.querySelectorAll('.glitch-title a').forEach(title => {
        title.addEventListener('mouseover', () => {
          if(!title.dataset.original) title.dataset.original = title.innerText;
          let iterations = 0;
          const interval = setInterval(() => {
            title.innerText = title.innerText.split("")
              .map((char, index) => {
                if(index < iterations) return title.dataset.original[index];
                return String.fromCharCode(65 + Math.floor(Math.random() * 26));
              }).join("");
            if(iterations >= title.dataset.original.length) clearInterval(interval);
            iterations += 1/2;
          }, 30);
        });
      });

      // 4. REVEAL & TYPEWRITER OBSERVER
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
            const tw = entry.target.querySelector('[data-typewriter]');
            if(tw && !tw.classList.contains('typed')) {
              typeWriter(tw); tw.classList.add('typed');
            }
          }
        });
      }, { threshold: 0.1 });

      // Garante que os componentes editados no Draft recebam o observer
      document.querySelectorAll('.reveal, article').forEach(el => {
        el.classList.add('reveal');
        observer.observe(el);
      });
    });
    //


